use quote::ToTokens;
use std::{io, path::Path};

static HEADER: &str = r#"//! GENERATED CODE - DO NOT EDIT
//!
//! This module was automatically generated by upstream-codegen.
//! Any changes made to this file will be lost when the code is regenerated.
"#;

pub fn file<P: AsRef<Path>, C: AsRef<[u8]>>(path: P, contents: C) -> io::Result<()> {
    let path = path.as_ref();
    let contents = contents.as_ref();

    // check if the file actually needs to be updated
    if path.exists() {
        let existing = std::fs::read(path)?;
        if existing == contents {
            return Ok(());
        }
    }

    if let Some(parent) = path.parent() {
        std::fs::create_dir_all(parent)?;
    }

    std::fs::write(path, contents)
}

/// Writes `tokens` to `path` as the source of a generated module.
///
/// The source is a function of the tokens alone, so one builder writes the same bytes in every build
/// on every host. Those bytes are an input of the compile cache key of the crate that includes them
/// (sccache hashes every source file in the compile's dep-info), and that crate's rlib is an input of
/// the key of every crate above it.
///
/// `prettyplease` lays the tokens out in-process and no external formatter runs. The `rustfmt` this
/// once took from `PATH` failed in some build containers and not others, most often on a build
/// script's first file, and a failed call kept prettyplease's layout, so one commit compiled to a
/// different key in each container. The module opens with `#![cfg_attr(rustfmt, rustfmt::skip)]`, so
/// `cargo fmt` leaves generated files as written.
pub fn rust<P: AsRef<Path>>(path: P, tokens: impl ToTokens) -> io::Result<()> {
    let path = path.as_ref();
    file(path, render(path, tokens))
}

/// The source [`rust`] writes for `tokens`. `path` only names the file in a parse failure's panic.
pub(crate) fn render(path: &Path, tokens: impl ToTokens) -> String {
    let mut parsed: syn::File = syn::parse2(tokens.to_token_stream()).unwrap_or_else(|e| {
        panic!(
            "failed to parse generated tokens for {}: {e}",
            path.display()
        )
    });

    parsed
        .attrs
        .insert(0, syn::parse_quote!(#![cfg_attr(rustfmt, rustfmt::skip)]));

    format!("{HEADER}\n\n{}", prettyplease::unparse(&parsed))
}

#[cfg(test)]
mod tests {
    use super::*;
    use quote::quote;

    fn tokens() -> proc_macro2::TokenStream {
        quote! {
            #![allow(dead_code)]
            pub mod endpoint;
            pub trait Env: core::fmt::Debug + Send + Sync + Clone + 'static {}
            impl<T> Env for T where T: core::fmt::Debug + Send + Sync + Clone + 'static {}
        }
    }

    #[test]
    fn the_source_is_a_function_of_the_tokens_alone() {
        let a = render(Path::new("/one/src/generated.rs"), tokens());
        let b = render(Path::new("/two/other/src/generated.rs"), tokens());

        assert_eq!(a, b);
        assert!(a.starts_with(HEADER), "{a}");
        assert!(!a.contains("/one") && !a.contains("/two"), "{a}");
    }

    #[test]
    fn the_source_opens_with_the_rustfmt_skip_attribute() {
        let source = render(Path::new("generated.rs"), tokens());
        let parsed: syn::File = syn::parse_str(&source).unwrap();

        // The header's `//!` lines parse as inner `doc` attributes; the skip is the first attribute
        // after them, ahead of the module's own.
        let attrs: Vec<String> = parsed
            .attrs
            .iter()
            .filter(|attr| !attr.path().is_ident("doc"))
            .map(|attr| attr.meta.to_token_stream().to_string())
            .collect();
        assert_eq!(
            attrs,
            [
                quote!(cfg_attr(rustfmt, rustfmt::skip)).to_string(),
                quote!(allow(dead_code)).to_string(),
            ],
            "{source}"
        );
    }
}
